cat > /tmp/lint_probe_test.go << 'EOF'
package mission

import "testing"

func TestProbeGlobCoverage(t *testing.T) {
	c := &Contract{
		WriteSet: []string{"docs/**"},
		Inputs:   Inputs{Files: []string{"docs/audited-delegation.md"}},
		SuccessCriteria: []string{"x"},
	}
	ws := lintInputsNotInWriteSet(c, nil)
	t.Logf("warnings: %+v", ws)
	if len(ws) != 0 {
		t.Errorf("expected no warning (semantically covered), got: %+v", ws)
	}
}
EOF
cp /tmp/lint_probe_test.go internal/mission/zzz_probe_test.go
go test ./internal/mission/ -run TestProbeGlobCoverage -v 2>&1 | tail -30
rm internal/mission/zzz_probe_test.go

